		.section 	code

; ************************************************************************************************
;
;									calculate ATN(x)
;
; ************************************************************************************************

FloatArcTan:
		jsr 	FloatNormalise 					; normalise x

		lda 	NSStatus,x 						; save sign, make absolute
		pha
		stz 	NSStatus,x

		lda 	NSExponent,x 					; $80000000 ^ $E1 is 1.0, so an exponent of -31
		cmp 	#$E1 							; or more means |x| >= 1 and needs the reciprocal.
		bcc 	_UANoFixup 						; ($E2 while the mantissa normalised to bit 30.)

		txa 									; value in +1
		tay
		iny
		jsr 	CopyFloatXY
		lda 	#1 								; 1.0 in +0
		jsr 	FloatSetByte
		inx
		jsr 	FloatDivide
		bcs 	_FATError

		jsr 	CoreAtn 						; calculate the root
		jsr 	CompletePolynomial
		jsr 	FloatNegate 					; make -ve

		.pushfloat Const_PiDiv2 				; add Pi/2
		jsr 	FloatAdd
		bra 	_UAComplete

_UANoFixup:		
		jsr 	CoreAtn
		jsr 	CompletePolynomial
_UAComplete:

		pla 									; apply the result.
		eor 	NSStatus,x
		sta 	NSStatus,x
		clc
		rts

_FATError:
		pla
		sec
		rts

		.send 	code

