		.section 	code

; ************************************************************************************************
;
;									calculates LOG()
;
; ************************************************************************************************

CoreLog: 	
		lda 	#LogCoefficients & $FF
		ldy 	#LogCoefficients >> 8
		jmp 	CorePolySquared

		.send 	code

